import itertools, os, random, subprocess, sys, time
try:
    import lcs

    def naive(a, b):
        prev = [0] * (len(b) + 1)
        for ca in a:
            cur = [0] * (len(b) + 1)
            for j, cb in enumerate(b, 1):
                if ca == cb:
                    cur[j] = prev[j - 1] + 1
                else:
                    x = prev[j]
                    y = cur[j - 1]
                    cur[j] = x if x >= y else y
            prev = cur
        return prev[-1]

    def ok(a, b):
        return lcs._lcs(a, b) == naive(a, b)

    good = True
    S2 = [''.join(p) for n in range(7) for p in itertools.product('ab', repeat=n)]
    for a in S2:
        for b in S2:
            if not ok(a, b):
                good = False
                break
        if not good:
            break

    if good:
        S3 = [''.join(p) for n in range(5) for p in itertools.product('abc', repeat=n)]
        for a in S3:
            for b in S3:
                if not ok(a, b):
                    good = False
                    break
            if not good:
                break

    rnd = random.Random(98765)
    alphabet = 'abcdé中 '
    if good:
        for _ in range(300):
            a = ''.join(rnd.choice(alphabet) for _ in range(rnd.randrange(0, 25)))
            b = ''.join(rnd.choice(alphabet) for _ in range(rnd.randrange(0, 25)))
            if not ok(a, b):
                good = False
                break

    path = os.path.join(os.path.dirname(os.path.abspath(lcs.__file__)), 'lcs.py')
    cli_cases = [
        ('abcde', 'ace', 3),
        ('abc', 'ac', 2),
        ('', '', 0),
        ('a', '', 0),
        (' AG GT', 'GTA', 2),
        ('aé中', 'é中a', 2),
        ('x' * 3000, 'x' * 3000, 3000),
    ]
    if good:
        for a, b, exp in cli_cases:
            p = subprocess.run(
                [sys.executable, path],
                input=a + '\n' + b + '\n',
                capture_output=True,
                text=True,
                encoding='utf-8',
            )
            if p.returncode != 0 or p.stdout.strip() != str(exp):
                good = False
                break

    if good:
        if naive('a' * 10 + 'b' * 10, 'b' * 10 + 'a' * 10) != 10:
            good = False
        elif lcs._lcs('a' * 1500 + 'b' * 1500, 'b' * 1500 + 'a' * 1500) != 1500:
            good = False

    rr = random.Random(4242)
    A = ''.join(rr.choice('acgt') for _ in range(3000))
    B = ''.join(rr.choice('acgt') for _ in range(3000))
    expected_big = lcs._lcs(A, B)
    t0 = time.perf_counter()
    reps = 0
    while time.perf_counter() - t0 < 0.45:
        v = lcs._lcs(A, B)
        reps += 1
        if v != expected_big:
            good = False
            break
    if reps == 0:
        good = False

    print(1000 if good else 0)
except Exception:
    print(0)
